def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    sep = next((r for r, row in enumerate(grid)
                if len(set(row)) == 1 and row[0] != bg), None)
    if sep is None:
        return [row[:] for row in grid]
    divider = grid[sep][0]

    pts = [(r, c) for r in range(h) for c in range(w)
           if grid[r][c] not in (bg, divider)]
    if not pts:
        return [row[:] for row in grid]

    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    shape = [grid[r][c0:c1 + 1] for r in range(r0, r1 + 1)]
    height = len(shape)

    out = [row[:] for row in grid]
    for r, c in pts:
        out[r][c] = bg

    if r1 < sep:  # object approaches divider from above
        top = sep - height
        for dr, row in enumerate(shape):
            for dc, value in enumerate(row):
                if value != bg:
                    out[top + dr][c0 + dc] = value
        marker = top - 1
    else:  # object approaches divider from below
        top = sep + 1
        for dr, row in enumerate(shape):
            for dc, value in enumerate(row):
                if value != bg:
                    out[top + dr][c0 + dc] = value
        marker = top + height

    if 0 <= marker < h:
        out[marker] = [8] * w
    return out
